--
-- Name: chunks; Type: TABLE; Schema: declaration_qa; Owner: -
--

CREATE TABLE declaration_qa.chunks (
    id bigint NOT NULL,
    document_id bigint NOT NULL,
    parent_chunk_id bigint,
    chunk_uid character varying(180) NOT NULL,
    chunk_type character varying(20) NOT NULL,
    chunk_index integer DEFAULT 0 NOT NULL,
    content text NOT NULL,
    content_hash character varying(80) DEFAULT ''::character varying NOT NULL,
    token_count integer DEFAULT 0 NOT NULL,
    embedding_id character varying(180) DEFAULT ''::character varying NOT NULL,
    vector_collection character varying(160) DEFAULT ''::character varying NOT NULL,
    source_url text DEFAULT ''::text NOT NULL,
    audit_node character varying(80) DEFAULT ''::character varying NOT NULL,
    status character varying(20) DEFAULT 'published'::character varying NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chunks_chunk_index_check CHECK ((chunk_index >= 0)),
    CONSTRAINT chunks_chunk_type_check CHECK (((chunk_type)::text = ANY ((ARRAY['parent'::character varying, 'child'::character varying])::text[]))),
    CONSTRAINT chunks_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'published'::character varying, 'deprecated'::character varying])::text[]))),
    CONSTRAINT chunks_token_count_check CHECK ((token_count >= 0))
);


