-- Name: documents; Type: TABLE; Schema: declaration_qa; Owner: -
--

CREATE TABLE declaration_qa.documents (
    id bigint NOT NULL,
    document_uid character varying(120) DEFAULT ''::character varying NOT NULL,
    knowledge_base_id bigint NOT NULL,
    title character varying(255) NOT NULL,
    filename character varying(255) DEFAULT ''::character varying NOT NULL,
    content_type character varying(120) DEFAULT 'text/plain'::character varying NOT NULL,
    source_url text DEFAULT ''::text NOT NULL,
    raw_text text NOT NULL,
    text_preview text DEFAULT ''::text NOT NULL,
    content_hash character varying(80) DEFAULT ''::character varying NOT NULL,
    audit_node character varying(80) DEFAULT ''::character varying NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    version_group_uid character varying(120) DEFAULT ''::character varying NOT NULL,
    version_no integer DEFAULT 1 NOT NULL,
    rollout_percent integer DEFAULT 100 NOT NULL,
    change_note text DEFAULT ''::text NOT NULL,
    published_at timestamp with time zone,
    deprecated_at timestamp with time zone,
    chunk_count integer DEFAULT 0 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text DEFAULT ''::text NOT NULL,
    created_by bigint,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT documents_chunk_count_check CHECK ((chunk_count >= 0)),
    CONSTRAINT documents_rollout_percent_check CHECK (((rollout_percent >= 0) AND (rollout_percent <= 100))),
    CONSTRAINT documents_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'indexing'::character varying, 'published'::character varying, 'failed'::character varying, 'deprecated'::character varying])::text[]))),
    CONSTRAINT documents_version_no_check CHECK ((version_no > 0))
);


